insert into audit_backup.rewrites_20261122_proposals (locale, slug, field, col, path, decision, old_text, new_text)
values
  ('de', 'aeolian-islands', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Die Aeolian Islands (ee-OH-lee-ən; italienisch: Isole Eolie [ˈiːzole eˈɔːlje]; sizilianisch: Ìsuli Eoli), manchmal auch als Lipari-Inseln oder Lipari-Gruppe (LIP-ər-ee, italienisch: [ˈliːpari]) nach ihrer größten Insel bezeichnet, sind ein vulkanisches Archipel im Tyrrhenischen Meer nördlich von Sizilien, das nach Aeolus benannt werden soll, dem mythischen Herrscher der Winde. Die Bewohner der Inseln sind als Äoler bekannt (italienisch: Eoliani). Die Inseln hatten eine ständige Bevölkerung von 14.224 bei der Volkszählung [datiert Quelle]; die letzte offizielle Schätzung ist 15.419 zum 1. Januar [datiert Quelle]. Die Aeolian Islands sind im Sommer ein beliebtes Touristenziel und ziehen jährlich bis zu 600.000 Besucher an.', 'Die Äolischen Inseln, nach ihrer größten Insel auch Liparische Inseln genannt, sind ein vulkanischer Archipel im Tyrrhenischen Meer nördlich von Sizilien. Ihr Name soll auf Aiolos zurückgehen, den mythischen Herrscher der Winde. Die Bewohner heißen Äolier (italienisch: Eoliani). Im Sommer sind die Inseln ein beliebtes Reiseziel und ziehen jährlich bis zu 600.000 Besucher an.'),
  ('de', 'albanian-alps-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Alpen von Albanien Nationalpark ist der größte Nationalpark in Albanien. Der in [datierter Quelle] eingerichtete Nationalpark liegt im Norden Albaniens und umfasst eine Fläche von 8.844,65 ha. Die prominenteste Gebirgskette sind die albanischen Alpen, die auch der Namensgeber des Nationalparks sind. Die meisten Gipfel Albaniens über 2.000 m befinden sich hier, darunter der höchste Gipfel der Dinariden, Maja e Jezercës. Die geologische Formation wird von hohem Gelände dominiert, während sie eine Vielzahl von natürlichen Merkmalen hat, darunter Gletscher, Täler, Flüsse, Berge, Wasserfälle, dichte Wälder und mehrere Felsformationen. Es zeichnet sich durch seine sehr abgelegenen Gebiete aus, die ein großes erhaltenes Ökosystem haben, das in erster Linie von unberührter Qualität unberührt ist. Der Park wurde gegründet, um verschiedene Ökosysteme und Biodiversität sowie das kulturelle und historische Erbe der Region zu schützen. Die Region wurde auch als ein wichtiges Vogel- und Pflanzengebiet identifiziert.', 'Der Nationalpark Albanische Alpen ist der größte Nationalpark Albaniens. Er liegt im Norden des Landes und umfasst 8.844,65 Hektar. Prägend sind die Albanischen Alpen, nach denen der Park benannt ist: Hier liegen die meisten Gipfel Albaniens über 2.000 m, darunter die Maja e Jezercës, der höchste Berg der Dinariden. Das hohe, vielfältige Gelände bietet Gletscher, Täler, Flüsse, Wasserfälle, dichte Wälder und Felsformationen; in sehr abgelegenen Gebieten ist das Ökosystem weitgehend unberührt. Der Park schützt Ökosysteme, Artenvielfalt und das kulturelle Erbe der Region und gilt zudem als bedeutendes Vogel- und Pflanzengebiet.'),
  ('de', 'ariege-pyrenees-regional-natural-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Mit rund 2.468 km2 umfasst es 138 Gemeinden seit dem 1. Januar [datiert Quelle] und 46.000 Einwohner.', 'Ein regionaler Naturpark von rund 2.468 km2, der etwa 40 % des Departements Ariège in den Pyrenäen einnimmt.'),
  ('de', 'basque-coast-unesco-global-geopark', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Baskische Küsten-Geopark (baskische Sprache: Euskal Kostaldeko Geoparkea), formell Basque Coast UNESCO Global Geopark, ist ein Gebiet des Baskenlandes im Norden Spaniens, das Mitglied des Europäischen Geopark-Netzwerks in [datierter Quelle] wurde, einem von mehreren globalen Geoparks in Spanien. Es umfasst 89 Quadratkilometer Landschaft mit einer 23 km langen Klippenküste am Golf von Biskaya. Im Landesinneren besteht es aus einem hügeligen Land, das bis zu Sesiarte reicht, das 755 m über dem Meeresspiegel liegt. Die wichtigsten Gemeinden im Geopark sind Zumaia, Deba und Mutriku. Die A8 Cantabrian Autobahn verläuft Ost-West durch den Geopark.', 'Der Geopark Baskische Küste (baskisch: Euskal Kostaldeko Geoparkea), offiziell UNESCO Global Geopark Baskische Küste, liegt im Baskenland im Norden Spaniens und gehört zum Europäischen Geopark-Netzwerk. Er umfasst 89 Quadratkilometer Land mit einer 23 km langen Steilküste am Golf von Biskaya. Im Hinterland steigt das Hügelland bis zum 755 m hohen Sesiarte an. Die wichtigsten Orte sind Zumaia, Deba und Mutriku; die Autobahn A8 durchquert den Geopark von Ost nach West.'),
  ('de', 'bieszczady-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Bieszczady National Park ist der drittgrößte Nationalpark Polens in der Subkarpaten-Woiwodschaft in der äußersten südöstlichen Ecke des Landes. In [datiert Quelle] wurde der Nationalpark ein UNESCO-Weltkulturerbe .', 'Der Bieszczady-Nationalpark ist der drittgrößte Nationalpark Polens. Er liegt in der Woiwodschaft Karpatenvorland, ganz im Südosten des Landes.'),
  ('de', 'bieszczady-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'In [datiert Quelle] wurde der Nationalpark ein UNESCO-Weltkulturerbe .', 'Der Bieszczady-Nationalpark ist der drittgrößte Nationalpark Polens, ganz im Südosten des Landes.'),
  ('de', 'black-forest-central-north-nature-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Naturpark Mittel-/Nordschwarzwald (deutsch: Naturpark Schwarzwald Mitte/Nord) liegt in Baden-Württemberg. Es umfasst eine Fläche von 3.750 km2 und wurde im Dezember gegründet [datiert Quelle]. Ab [datiert Quelle] ist es der drittgrößte Naturpark in Deutschland.', 'Der Naturpark Schwarzwald Mitte/Nord liegt in Baden-Württemberg und umfasst eine Fläche von 3.750 km2.'),
  ('de', 'breheimen-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Breheimen National Park ist ein Nationalpark, der in [datierter Quelle] eingerichtet wurde. Der Park befindet sich in der Gemeinde Skjåk und der Gemeinde Lom im Kreis Innlandet und in der Gemeinde Luster im Kreis Vestland, Norwegen. Der Park umfasst 1.671 Quadratkilometer des Breheimer Gebirges. Der Park umfasst einige der feuchtesten und trockensten Landschaften des Landes, mit Landschaften, die über Hunderttausende von Jahren von Gletschern, Lawinen und anderen geologischen Prozessen geformt wurden. Besucher begegnen alles von üppigen transhumanzbewirtschafteten Tälern bis hin zu kargen Plateaus, aufsteigenden Gipfeln und aktiven Gletschern.', 'Der Breheimen-Nationalpark liegt in den Gemeinden Skjåk und Lom (Provinz Innlandet) sowie in Luster (Provinz Vestland) in Norwegen. Er umfasst 1.671 Quadratkilometer des Gebirgszugs Breheimen mit einigen der nassesten und trockensten Landschaften des Landes, die über Hunderttausende von Jahren von Gletschern, Lawinen und anderen geologischen Prozessen geformt wurden. Besucher erleben grüne Täler mit Almwirtschaft ebenso wie karge Hochebenen, hohe Gipfel und aktive Gletscher.'),
  ('de', 'breheimen-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Breheimen National Park ist ein Nationalpark, der in [datierter Quelle] eingerichtet wurde.', 'Der Breheimen-Nationalpark umfasst 1.671 Quadratkilometer des Gebirgszugs Breheimen in Norwegen.'),
  ('de', 'catalan-pyrenees-regional-natural-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Regionale Naturpark der katalanischen Pyrenäen ist ein Schutzgebiet im westlichen Drittel des französischen Departements der östlichen Pyrenäen. Gegründet im März [datiert Quelle], ist es der erste regionale Naturpark in den Pyrenäen.', 'Der Regionale Naturpark der Katalanischen Pyrenäen ist ein Schutzgebiet im westlichen Drittel des französischen Departements Pyrénées-Orientales. Er ist der erste regionale Naturpark der Pyrenäen.'),
  ('de', 'catalan-pyrenees-regional-natural-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Gegründet im März [datiert Quelle], ist es der erste regionale Naturpark in den Pyrenäen.', 'Der erste regionale Naturpark der Pyrenäen umfasst das westliche Drittel des Departements Pyrénées-Orientales.'),
  ('de', 'caves-of-barac', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Die Caves of Barać auch bekannt als Barać Höhlen oder Barać Höhlen sind eine Gruppe von Höhlen in der Nähe des Dorfes Nova Kršlja in der Gemeinde Rakovica, Kroatien. Im Jahr 1892 wurden die Höhlen für Besucher geöffnet, aber nach dem Zweiten Weltkrieg verlassen und vergessen. Im Juli [datiert Quelle] die Upper Caves of Barać wurden wieder für Besucher geöffnet.', 'Die Barać-Höhlen sind eine Höhlengruppe beim Dorf Nova Kršlja in der Gemeinde Rakovica in Kroatien. 1892 wurden sie für Besucher geöffnet, nach dem Zweiten Weltkrieg jedoch aufgegeben und vergessen. Die Oberen Barać-Höhlen wurden später wieder für Besucher geöffnet.'),
  ('de', 'conca-dorupatrimoniogolfe-de-saint-florent', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Conca d''Oru, die Weinberge von Patrimonio - Golf von Saint-Florent, erhielt im März das Label Grand Site of France [datiert Quelle]. Es ist der siebzehnte gekennzeichnete Ort und der zweite in Korsika.', 'Conca d''Oru, die Weinberge von Patrimonio und der Golf von Saint-Florent tragen das Label Grand Site de France. Es ist die siebzehnte ausgezeichnete Stätte Frankreichs und die zweite auf Korsika.'),
  ('de', 'faerder-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Færder National Park ist ein Nationalpark in der Gemeinde Færder in Vestfold, Norwegen. Es ist hauptsächlich ein Meerespark und umfasst einige Inseln und Küstengebiete östlich der größeren Inseln Nøtterøy und Tjøme. Im Osten grenzt der Nationalpark an den Ytre Hvaler Nationalpark. Færder umfasst eine Fläche von 340 km2, davon 325 km2 Meer und 15 km2 Land. Der Park wurde am 23. August gegründet [datiert Quelle]. Der Park umfasst große Teile des Archipels von Bolærne sowie den geschützten Leuchtturm Færder und die Ruinen des Store Færder Lighthouse mit seinen zugehörigen geschützten Gebäuden.', 'Der Færder-Nationalpark liegt in der Gemeinde Færder in der Provinz Vestfold in Norwegen. Er ist überwiegend ein Meeresnationalpark mit Inseln und Küstenabschnitten östlich der größeren Inseln Nøtterøy und Tjøme und grenzt im Osten an den Ytre-Hvaler-Nationalpark. Færder umfasst 340 km2, davon 325 km2 Meer und 15 km2 Land. Zum Park gehören große Teile des Bolærne-Archipels, der denkmalgeschützte Leuchtturm Færder sowie die Ruinen des Leuchtturms Store Færder mit seinen geschützten Nebengebäuden.'),
  ('de', 'garrawilla-national-park-nsw', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Garrawilla National Park wurde im Dezember [datiert Quelle] erstellt. Es umfasst eine Fläche von 937 Hektar. Dieser Park liegt auf der nördlichen Seite des Oxley Highway etwa auf halbem Weg zwischen Coonabarabran und Mullaley in New South Wales, Australien.', 'Der Garrawilla-Nationalpark umfasst 937 Hektar. Er liegt an der Nordseite des Oxley Highway, etwa auf halbem Weg zwischen Coonabarabran und Mullaley in New South Wales, Australien.'),
  ('de', 'garrawilla-national-park-nsw', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Garrawilla National Park wurde im Dezember [datiert Quelle] erstellt.', 'Der Garrawilla-Nationalpark liegt am Oxley Highway zwischen Coonabarabran und Mullaley in New South Wales.'),
  ('de', 'grands-causses-regional-natural-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Parc naturel régional des Grands Causses ist ein französischer Naturpark, der am 6. Mai 1995 gegründet und in [datierter Quelle] erneuert wurde. Es liegt in Occitanie, an der Südspitze des Zentralmassivs und umfasst den südlichen Teil des Departements Aveyron und den nördlichen Teil des Departements Hérault.', 'Der Parc naturel régional des Grands Causses ist ein französischer Regionaler Naturpark, der am 6. Mai 1995 gegründet wurde. Er liegt in Okzitanien am Südrand des Zentralmassivs und umfasst den Süden des Departements Aveyron und den Norden des Departements Hérault.'),
  ('de', 'guadarrama-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sierra de Guadarrama National Park (auf Spanisch: Parque Nacional de la Sierra de Guadarrama) ist ein Nationalpark in Spanien mit einer Fläche von fast 34.000 Hektar, der fünftgrößte in Spaniens Nationalparksystem. Die Guadarrama-Bergkette (Sistema Central) enthält einige ökologisch wertvolle Gebiete in der Gemeinschaft Madrid und Kastilien und León (Provinzen Segovia und Ávila). Das Gesetz, das den kürzlich genehmigten Nationalpark regelt, wurde am 26. Juni in der BOE veröffentlicht [datiert Quelle] ([datiert Quelle]-06-26).', 'Der Nationalpark Sierra de Guadarrama (spanisch: Parque Nacional de la Sierra de Guadarrama) umfasst knapp 34.000 Hektar und ist der fünftgrößte Nationalpark Spaniens. Das Gebirge Guadarrama (Sistema Central) birgt ökologisch wertvolle Gebiete in der Region Madrid und in Kastilien-León (Provinzen Segovia und Ávila).'),
  ('de', 'hump-ridge-track', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Hump Ridge Track, auch Tuatapere Hump Ridge Track genannt, ist ein 60-62 km langer Wanderweg, der teilweise im Fiordland National Park in Neuseeland liegt. Der Track wurde in [datierter Quelle] eröffnet und wird privat im Auftrag des Tuatapere Hump Ridge Track Charitable Trust betrieben.', 'Der Hump Ridge Track, auch Tuatapere Hump Ridge Track genannt, ist ein 60 bis 62 km langer Wanderweg, der teilweise im Fiordland-Nationalpark in Neuseeland verläuft. Er wird privat im Auftrag des Tuatapere Hump Ridge Track Charitable Trust betrieben.'),
  ('de', 'junkerdal-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Der 682 Quadratkilometer große Park wurde in [datierter Quelle] eröffnet.', 'Ein 682 km2 großer Nationalpark in Saltdal und Fauske in der Provinz Nordland, an der Grenze zu Schweden.'),
  ('de', 'kosterhavet-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Kosterhavet National Park ist der erste nationale Meerespark in Schweden, der im September eingeweiht wurde [datiert Quelle]. Es ist Teil des Skagerrak-Meeres und befindet sich in den Gemeinden Strömstad und Tanum in Bohuslän, Västra Götaland, Schweden. Es besteht aus dem Meer und den Küsten rund um die Koster-Inseln, mit Ausnahme von allem anderen auf den Inseln. Im Norden grenzt er an den norwegischen Marinepark Ytre Hvaler.', 'Der Kosterhavet-Nationalpark ist der erste Meeresnationalpark Schwedens. Er gehört zum Skagerrak und liegt in den Gemeinden Strömstad und Tanum in Bohuslän (Provinz Västra Götaland). Er umfasst das Meer und die Uferzonen rund um die Koster-Inseln, nicht aber das übrige Inselland, und grenzt im Norden an den norwegischen Meeresnationalpark Ytre Hvaler.'),
  ('de', 'kotychi-and-strofylia-wetlands-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Es wurde ein Nationalpark in [datiert Quelle] erklärt.', 'Geschützte Feuchtgebiete und Wälder in Achaia und Ilia mit dem Kotychi-See, dem Strofylia-Wald und Kap Araxos.'),
  ('de', 'langsua-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Langsua National Park wurde in [datierter Quelle] gegründet. Der Park besteht aus einem Gesamtschutzgebiet von 537,1 Quadratkilometern. Sie liegt im norwegischen Komitat Innlandet und umfasst Teile der Gemeinden Øystre Slidre, Nord-Aurdal, Nordre Land, Gausdal, Sør-Fron und Nord-Fron.', 'Der Langsua-Nationalpark schützt 537,1 Quadratkilometer in der Provinz Innlandet in Norwegen und erstreckt sich über Teile der Gemeinden Øystre Slidre, Nord-Aurdal, Nordre Land, Gausdal, Sør-Fron und Nord-Fron.'),
  ('de', 'langsua-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Langsua National Park wurde in [datierter Quelle] gegründet.', 'Der Langsua-Nationalpark schützt 537,1 Quadratkilometer in der Provinz Innlandet in Norwegen.'),
  ('de', 'les-deux-caps-blanc-nez-gris-nez', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'In [datierter Quelle] erhöht sich sein Umfang von acht auf achtzehn Gemeinden.', 'Ein Grand Site de France an der Opalküste zwischen Boulogne-sur-Mer und Calais, gegenüber von England.'),
  ('de', 'liechtensteinklamm', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'CLEAR', 'Liechtensteinklamm ist täglich von Anfang Mai bis 30. September [datiert Quelle] von 09:00 bis 18:00 Uhr (letzter Eintritt um 18:00 Uhr) geöffnet.', ''),
  ('de', 'liechtensteinklamm', 'tagline', 'fields', '{tagline}'::text[], 'CLEAR', 'Liechtensteinklamm ist täglich von Anfang Mai bis 30. September geöffnet [datiert Quelle] von 09:00 bis 18:00 Uhr (zuletzt)', ''),
  ('de', 'lomsdal-visten-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Lomsdal-Visten Nationalpark ist ein norwegischer Nationalpark, der am 26. Juni gegründet wurde [datiert Quelle]. Der Park besteht aus einem Gesamtschutzgebiet von 1.102 Quadratkilometern. Es befindet sich im norwegischen Verwaltungsbezirk Nordland und umfasst Teile der Gemeinde Brønnøy, der Gemeinde Vevelstad, der Gemeinde Grane und der Gemeinde Vefsn.', 'Der Lomsdal-Visten-Nationalpark ist ein norwegischer Nationalpark mit einer Schutzfläche von 1.102 Quadratkilometern. Er liegt in der Provinz Nordland und erstreckt sich über Teile der Gemeinden Brønnøy, Vevelstad, Grane und Vefsn.'),
  ('de', 'loonse-en-drunense-duinen', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Es wurde als Nationalpark seit [datiert Quelle].', 'Ein 35 km2 großer Nationalpark zwischen Tilburg, Waalwijk und ''s-Hertogenbosch im Süden der Niederlande.'),
  ('de', 'lorship-bertiz-natural-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Der Naturpark Señorío de Bertiz (offiziell Bertizko Jaurerria Parke Naturala) [datiert Quelle] ha, befindet sich', 'Señorío de Bertiz ist ein Naturpark im Nordwesten Navarras in Spanien, ausgewiesen 1984.'),
  ('de', 'marine-natural-park-of-picardy-and-opale-coast', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Parc naturel marin des estuaires picards et de la mer d''Opale ist ein französischer Meeresnaturpark, der im Dezember [dated source] gegründet wurde. Er befindet sich vor den sieben Küstenflüssen, von Süden nach Norden, der Bresle, der Somme, der Authie, der Canche, der Liane, dem Wimereux und der Slack. Sein Hauptsitz befindet sich in Écault auf dem Gebiet von Saint-Étienne-au-Mont, im Pas-de-Calais.', 'Der Parc naturel marin des estuaires picards et de la mer d''Opale ist ein französischer Meeresnaturpark vor den Mündungen von sieben Küstenflüssen: von Süden nach Norden Bresle, Somme, Authie, Canche, Liane, Wimereux und Slack. Sein Sitz ist in Écault in der Gemeinde Saint-Étienne-au-Mont (Pas-de-Calais).'),
  ('de', 'marker-wadden-in-het-markermeer', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Die erste Insel wurde am 24. September eingeweiht [datiert Quelle].', 'Die Marker Wadden sind ein künstlicher Archipel und ein Naturschutzgebiet im Markermeer in den Niederlanden.'),
  ('de', 'midden-delfland', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Midden-Delfland (niederländisch: [ˌmɪdəˈdɛlflɑnt]) ist eine Gemeinde in der Region Westland in der Provinz Südholland in den Niederlanden. Es hatte eine Bevölkerung von 19.355 in [datierter Quelle] und bedeckt eine Fläche von 49,38 km2, von denen 2,19 km2 Wasser sind.', 'Midden-Delfland ist eine Gemeinde in der Region Westland in der Provinz Südholland in den Niederlanden. Sie umfasst 49,38 km2, davon 2,19 km2 Wasserfläche.'),
  ('de', 'midden-delfland', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Es hatte eine Bevölkerung von 19.355 in [datierter Quelle] und bedeckt eine Fläche von 49,38 km2, von denen 2,19 km2 Wasser sind.', 'Midden-Delfland ist eine 49,38 km2 große Gemeinde in der Region Westland in Südholland.'),
  ('de', 'mont-ventoux', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der regionale Naturpark Mont-Ventoux, in der provenzalischen Pargue dóu Ventours, ist ein regionaler Naturpark, der per Dekret am 28. Juli [datiert Quelle] geschaffen wurde. Es ist der 55. regionale Naturpark in Frankreich und der 9. in der Provence-Alpes-Côte d''Azur.', 'Der Regionale Naturpark Mont-Ventoux (provenzalisch: pargue dóu Ventours) ist der 55. Regionale Naturpark Frankreichs und der 9. in der Region Provence-Alpes-Côte d''Azur.'),
  ('de', 'nationaal-park-de-sallandse-heuvelrug', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'In [datiert Quelle] änderte die niederländische Regierung den Status des Gebiets in Nationalpark.', 'Die Sallandse Heuvelrug ist ein Nationalpark in Overijssel zwischen den Orten Hellendoorn und Holten.'),
  ('de', 'nationaal-park-duinen-van-texel', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Der Park umfasst etwa 43 km2 und erreichte den Status eines Nationalparks in [datierter Quelle].', 'Der Nationalpark Duinen van Texel umfasst rund 43 km2 Dünen und Küstenebenen auf der Insel Texel.'),
  ('de', 'national-park-drina', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Drina-Nationalpark ist der vierte Nationalpark in Bosnien und Herzegowina und der dritte in der Republika Srpska. Es wurde gegründet in [datiert Quelle]. Die nächste Stadt ist Srebrenica. Es befindet sich auf der anderen Seite der Drina in Bezug auf Tara Nationalpark in Serbien.', 'Der Nationalpark Drina ist der vierte Nationalpark in Bosnien und Herzegowina und der dritte in der Republika Srpska. Die nächstgelegene Stadt ist Srebrenica. Er liegt am gegenüberliegenden Ufer der Drina, gegenüber dem Tara-Nationalpark in Serbien.'),
  ('de', 'national-park-of-eastern-macedonia-and-thrace', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Nationalpark Ostmazedonien - Thrakien wurde in [datierter Quelle] gegründet und umfasste die bereits geschützten Gebiete von D. Nestos, L. Vistonidas, L. Ismaridas und deren weitere Gebiete. Der Feuchtgebietskomplex des Nationalparks ist aufgrund seiner großen Fläche und seines großen biologischen, ästhetischen, wissenschaftlichen, geomorphologischen und pädagogischen Wertes einer der wichtigsten in Griechenland. Ziel des Nationalparks ist es, Lebensräume und seltene Flora- und Faunaarten, die in der Region endemisch sind und brüten, effektiv zu schützen.', 'Der Nationalpark Ostmakedonien und Thrakien umfasst das bereits zuvor geschützte Nestos-Delta, den Vistonida-See, den Ismarida-See und ihr weiteres Umland. Sein Feuchtgebietskomplex gehört wegen seiner Größe und seines hohen biologischen, landschaftlichen, wissenschaftlichen, geomorphologischen und pädagogischen Werts zu den bedeutendsten Griechenlands. Ziel des Parks ist der Schutz von Lebensräumen und seltenen Pflanzen- und Tierarten, die in der Region heimisch sind oder hier brüten.'),
  ('de', 'national-park-of-messolonghi-aitoliko-lagoons', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'In [datierter Quelle] erstellt, umfasst es den größten Lagunenkomplex des Landes.', 'Der Nationalpark umfasst den größten Lagunenkomplex Griechenlands am Nordwestende des Golfs von Patras.'),
  ('de', 'nationalpark-mols-bjerge', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Mols Bjerge National Park oder Nationalpark Mols Bjerge ist ein dänischer Nationalpark in der Gegend als Mols Bjerge in Syddjurs Gemeinde, Zentraljütland bekannt, am 29. August eingeweiht [datiert Quelle]. Das Schutzgebiet ist 180 Quadratkilometer groß. Die Mols Hills, die eine Höhe von 137 Metern erreichen, sind zentral im Park gelegen und nehmen 2.500 ha ein. "Mehr als die Hälfte aller wilden dänischen Pflanzenarten" findet man bei Mols Bjerge.', 'Der Nationalpark Mols Bjerge ist ein dänischer Nationalpark im Gebiet Mols Bjerge in der Gemeinde Syddjurs in Mitteljütland. Das Schutzgebiet umfasst 180 Quadratkilometer. Im Zentrum liegen die bis zu 137 Meter hohen Mols-Hügel mit 2.500 Hektar. Mehr als die Hälfte aller wild wachsenden Pflanzenarten Dänemarks kommt in Mols Bjerge vor.'),
  ('de', 'nationalpark-thy', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Thy National Park ist ein Nationalparkgebiet in Thy, Dänemark, das am 22. August für die Öffentlichkeit geöffnet wurde [datiert Quelle]. Es liegt im Nordwesten Jütlands, entlang der Küste von Hanstholm nach Agger Tange und erstreckt sich über 55 km von Norden nach Süden und 5-12 km von Osten nach Westen. Die Gesamtfläche des Nationalparks beträgt 244 km2.', 'Der Nationalpark Thy liegt in der Landschaft Thy in Dänemark. Er erstreckt sich in Nordwestjütland entlang der Küste von Hanstholm bis Agger Tange, 55 km von Nord nach Süd und 5 bis 12 km von Ost nach West. Insgesamt umfasst er 244 km2.'),
  ('de', 'natural-park-of-serra-d-irta', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Naturpark Serra d''Irta (Valencian: Parc Natural de la Serra d''Irta, Spanisch: Parque Natural de la Sierra de Irta) ist ein Naturpark in der valencianischen Gemeinschaft, Südspanien. Es umfasst 7.744 Hektar Land sowie eine Küstenlinie des Meeresnaturreservats des angrenzenden Mittelmeers. Es wurde ein geschütztes Gebiet in [datiert Quelle] erklärt.', 'Der Naturpark Serra d''Irta (valencianisch: Parc Natural de la Serra d''Irta; spanisch: Parque Natural de la Sierra de Irta) liegt in der Valencianischen Gemeinschaft in Spanien. Er umfasst 7.744 Hektar Land sowie ein Meeresschutzgebiet an der angrenzenden Mittelmeerküste.'),
  ('de', 'naturpark-nissum-fjord', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Naturpark Nissum Fjord wurde als Pilotprojekt auf Anfrage des Nissum Fjord Network im Mai eingerichtet [datiert Quelle]. Der Naturpark erstreckt sich über 22.670 Hektar rund um den Nissum Fjord und ist der drittgrößte Naturpark Dänemarks. Der Naturpark wurde vom Open Air Council am 12. Dezember genehmigt [datiert Quelle].', 'Der Naturpark Nissum Fjord erstreckt sich über 22.670 Hektar rund um den Nissum Fjord und ist der drittgrößte Naturpark Dänemarks.'),
  ('de', 'naturpark-nissum-fjord', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Der Naturpark wurde vom Open Air Council am 12. Dezember genehmigt [datiert Quelle].', 'Der Naturpark Nissum Fjord umfasst 22.670 Hektar rund um den Fjord – der drittgrößte Naturpark Dänemarks.'),
  ('de', 'north-pindos-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'North Pindos National Park ist 230 km lang und 70 km breit, gegründet in [datierter Quelle] und gilt als eines der wichtigsten Gebiete auf nationaler und europäischer Ebene. Auch die Vielfalt der seltenen Arten sollte erwähnt werden, da fast alle großen Säugetiere des griechischen Festlandes in der Region gehostet werden. Insgesamt 60 Säugetierarten, 166 Vogelarten, 30 Reptilienarten, 14 Amphibienarten und 17 Fischarten sind im Park zu finden.', 'Der Nationalpark Nord-Pindos ist 230 km lang und 70 km breit und gilt als eines der wichtigsten Gebiete Griechenlands und Europas. Fast alle großen Säugetiere des griechischen Festlands leben hier: Insgesamt kommen im Park 60 Säugetier-, 166 Vogel-, 30 Reptilien-, 14 Amphibien- und 17 Fischarten vor.'),
  ('de', 'ostmarka-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Østmarka National Park ist ein norwegischer Nationalpark, der in [datierter Quelle] erstellt wurde. Es umfasst eine Fläche von 54 km2 in Østmarka, Oslo und Akershus Municipality Nordre Follo, Lørenskog, Røllen und Enebakk.', 'Der Østmarka-Nationalpark ist ein norwegischer Nationalpark und umfasst 54 km2 des Waldgebiets Østmarka in Oslo sowie in den Akershus-Gemeinden Nordre Follo, Lørenskog, Rælingen und Enebakk.'),
  ('de', 'paluma-range-national-park-qld', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'CLEAR', 'Am National Parks Day [datiert Quelle] kündigte die Regierung von Queensland die Hinzufügung von 6.510 Hektar zum Paluma Range National Park an.', ''),
  ('de', 'parc-naturel-regional-de-guyane', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Parc naturel régional de la Guyane ist ein französischer regionaler Naturpark, der [dated source] in Guyane gegründet wurde. Er ist in drei terrestrische Teile und zwei maritime Abschnitte unterteilt und umfasst das Gebiet von sechs Kommunen: Iracoubo, Mana, Ouanary, Roura, Saint-Georges und Sinnamary.', 'Der Regionale Naturpark Guayana ist ein französischer Regionaler Naturpark in Französisch-Guayana. Er besteht aus drei Land- und zwei Meeresteilen und erstreckt sich über sechs Gemeinden: Iracoubo, Mana, Ouanary, Roura, Saint-Georges und Sinnamary.'),
  ('de', 'parc-naturel-regional-des-baronnies-provencales', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der regionale Naturpark der provenzalischen Baronnies erstreckt sich über ein Alpenmassiv zwischen den Departements Drôme und Hautes-Alpes im Südosten Frankreichs. Dieser regionale Naturpark wurde am 26. Januar gegründet [datiert Quelle]. Es umfasst 104 Gemeinden ganz oder teilweise.', 'Der Regionale Naturpark Baronnies provençales erstreckt sich über ein Alpenmassiv zwischen den Departements Drôme und Hautes-Alpes im Südosten Frankreichs. Er umfasst ganz oder teilweise 104 Gemeinden.'),
  ('de', 'parc-naturel-regional-des-baronnies-provencales', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Dieser regionale Naturpark wurde am 26. Januar gegründet [datiert Quelle].', 'Ein regionaler Naturpark in einem Alpenmassiv zwischen Drôme und Hautes-Alpes, der 104 Gemeinden umfasst.'),
  ('de', 'parco-naturale-regionale-bosco-incoronata', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der regionale Naturpark Bosco Incoronata ist ein geschütztes Naturgebiet, das in [datierter Quelle] entlang des Flusses Cervaro etwa 12 Kilometer von der Stadt Foggia entfernt im Herzen der Apulientafel liegt.', 'Der Regionale Naturpark Bosco Incoronata ist ein Naturschutzgebiet am Fluss Cervaro, etwa 12 Kilometer von Foggia entfernt, mitten in der Tavoliere-Ebene Apuliens.'),
  ('de', 'parco-naturale-regionale-bosco-incoronata', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Der regionale Naturpark Bosco Incoronata ist ein Naturschutzgebiet, das in [datierter Quelle] entlang der', 'Ein Naturschutzgebiet am Fluss Cervaro, rund 12 Kilometer von Foggia in Apulien entfernt.'),
  ('de', 'parco-naturale-regionale-del-vulture', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Vulture Regional Natural Park ist ein Naturschutzgebiet, das im November gegründet wurde [datiert Quelle]. Dieser Regionalpark umfasst das Geiergebiet sowie einen Teil der Gemeindegebiete Atella, Barile, Ginestra, Melfi, Rapolla, Rionero in Vulture, Ripacandida, Ruvo del Monte und San Fele, die alle zur Provinz Potenza gehören.', 'Der Regionale Naturpark Vulture ist ein Naturschutzgebiet, das das Gebiet des Vulture und Teile der Gemeinden Atella, Barile, Ginestra, Melfi, Rapolla, Rionero in Vulture, Ripacandida, Ruvo del Monte und San Fele umfasst, alle in der Provinz Potenza.'),
  ('de', 'parco-naturale-regionale-del-vulture', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Der Vulture Regional Natural Park ist ein Naturschutzgebiet, das im November gegründet wurde [datiert Quelle]. Diese Reg.', 'Ein Naturschutzgebiet rund um den Vulture, mit einem Teil von Melfi, in der Provinz Potenza.'),
  ('de', 'parco-naturale-regionale-terra-delle-gravine', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Naturpark Terra delle Gravine ist ein Naturschutzgebiet in Apulien in [datierter Quelle]. Das Gebiet umfasst die Provinzen Brindisi und Taranto im Gebiet Murge.', 'Der Naturpark Terra delle Gravine ist ein Naturschutzgebiet in Apulien und umfasst Teile der Provinzen Brindisi und Tarent in der Murgia.'),
  ('de', 'ponga-nature-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der Naturpark Ponta ist ein spanischer Naturschutzraum, der sich im zentralen Bereich des Cantábrica-Gebirges mit einem Schutzgebiet von 20533 ha befindet, und die meisten von ihnen sind der Stadtrat von Ponta. Es sollte am Ende der Periode zuerst in den Reds Park aufgenommen werden und sein Name als Naturpark war später und mit eigener Identität. Es wurde durch Gesetz 4 / [datiert Quelle] erklärt.', 'Der Naturpark Ponga ist ein spanisches Naturschutzgebiet im zentralen Kantabrischen Gebirge mit einer Schutzfläche von 20.533 Hektar, die größtenteils in der Gemeinde Ponga liegt.'),
  ('de', 'reinheimen-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Reinheimen National Park ist ein Nationalpark in Norwegen, der in [datierter Quelle] eingerichtet wurde. Der Park besteht aus einem 1.969 Quadratkilometer großen zusammenhängenden geschützten Berggebiet. Es befindet sich in den Provinzen Møre og Romsdal und Innlandet in Norwegen. Der Park umfasst Teile der Gemeinden Lesja, Skjåk, Vågå, Lom, Fjord und Rauma. Der Park besteht aus einem Großteil der Tafjordfjella-Bergkette sowie dem Rentierlebensraum im nördlichen Teil des Ottadalen-Tals.', 'Der Reinheimen-Nationalpark ist ein norwegischer Nationalpark mit einem zusammenhängenden Gebirgsschutzgebiet von 1.969 Quadratkilometern in den Provinzen Møre og Romsdal und Innlandet. Er umfasst Teile der Gemeinden Lesja, Skjåk, Vågå, Lom, Fjord und Rauma, einen Großteil des Gebirges Tafjordfjella sowie die Rentiergebiete im Norden des Ottadalen.')
